import{_ as o,C as s,o as r,c as l,j as a,a as n,E as i,a6 as d}from"./chunks/framework.DIp0zHSV.js";const c="/dev/releases/2026.04.3.1/elbow-zones.webp",x=JSON.parse('{"title":"LCARdS 2026.04.3.1","description":"Text fields and zones across button, slider and elbow; state-based slider colours.","frontmatter":{"version":"2026.04.3.1","date":"2026-04-03T00:00:00.000Z","status":"released","summary":"Text fields and zones across button, slider and elbow; state-based slider colours.","breaking":false},"headers":[],"relativePath":"releases/2026.04.3.1.md","filePath":"releases/2026.04.3.1.md","lastUpdated":1791928403000}'),u={name:"releases/2026.04.3.1.md"};function h(p,e,m,b,f,g){const t=s("ReleaseMeta");return r(),l("div",null,[e[0]||(e[0]=a("h1",{id:"lcards-2026-04-3-1",tabindex:"-1"},[n("LCARdS 2026.04.3.1 "),a("a",{class:"header-anchor",href:"#lcards-2026-04-3-1","aria-label":'Permalink to "LCARdS 2026.04.3.1"'},"​")],-1)),i(t),e[1]||(e[1]=d('<h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="text-fields-zones" tabindex="-1">Text Fields &amp; Zones <a class="header-anchor" href="#text-fields-zones" aria-label="Permalink to &quot;Text Fields &amp; Zones&quot;">​</a></h3><p>LCARdS now ships a full text + zone layout system across Button, Slider, and Elbow cards.</p><img class="release-shot" alt="Debug zone overlay on an elbow card" src="'+c+'"><p><strong>Auto-zones</strong>: every card type automatically calculates named zones from its geometry (e.g. <code>horizontal_bar</code> / <code>vertical_bar</code> on an elbow, <code>track</code> on a slider, <code>body</code> on a button). No configuration required: they&#39;re always there.</p><p><strong>Text field routing</strong>: any text field can target a zone by name with <code>zone: &lt;name&gt;</code>. Positioning, padding, and font sizing all operate <em>within</em> the zone bounds.</p><p><strong>Proportional sizing</strong>: <code>font_size_percent: 100</code> makes cap-height glyphs fill the full zone height; pair with <code>stretch: true</code> to also fill the zone width. Both scale automatically as the card is resized.</p><p><strong>Custom zones</strong>: define additional zones under <code>config.zones</code> using pixels, percent, or a mix per axis. Custom zone names replace auto-calculated ones of the same name.</p><p><strong>Debug overlay</strong>: add <code>debug_zones: true</code> to any card to render a colour-coded zone overlay for layout design.</p><p>→ <a href="https://github.com/snootched/lcards/discussions/325" target="_blank" rel="noreferrer">Full announcement &amp; examples: <em>Text Fields &amp; Zones: LCARdS Dynamic and Customizable Text Layout System</em></a></p><h3 id="state-based-slider-colours" tabindex="-1">State-based Slider Colours <a class="header-anchor" href="#state-based-slider-colours" aria-label="Permalink to &quot;State-based Slider Colours&quot;">​</a></h3><p>Raised from issue <a href="https://github.com/snootched/lcards/issues/315" target="_blank" rel="noreferrer">#315</a> - the slider card has been updated with full state-based colour support across the components.</p><p>You can now:</p><ul><li>assign any colour to any state (just like buttons, gauge ticks, etc.)</li><li><code>match-light</code> colour for gradient start/end (<code>active</code> state)</li><li>optionally apply light brightness multiplier on each</li><li>independent colour selection for gradient start/end (<code>inactive</code> state)</li><li>filled/unfilled opacity still works (and is a multiplier if apply light brightness is also enabled)</li><li>state-based colours permit calculated colours as well (<code>alpha() lighten() darken() saturate() desaturate() mix()</code>)</li></ul><hr><h2 id="updates-fixes" tabindex="-1">Updates &amp; Fixes <a class="header-anchor" href="#updates-fixes" aria-label="Permalink to &quot;Updates &amp; Fixes&quot;">​</a></h2><ul><li>enhancement: colour/hue matching for coloured bulbs in white mode <a href="https://github.com/snootched/lcards/issues/314" target="_blank" rel="noreferrer">#314</a></li><li>many small fixes and enhancements</li></ul><hr><p>All changes: <a href="https://github.com/snootched/lcards/compare/2026.03.29.1...2026.04.3.1" target="_blank" rel="noreferrer">2026.03.29.1...2026.04.3.1</a></p>',19))])}const y=o(u,[["render",h]]);export{x as __pageData,y as default};
